@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="chat-container">
    <!-- Sidebar -->
    <div class="sidebar">
        <div class="sidebar-header">Channels</div>
        <div class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <div class="channel-item @(channel.Id == _activeChannel?.Id ? "active" : "")"
                         @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-info">
                            <div class="channel-name"># @channel.Name</div>
                            <div class="channel-desc">@TruncateText(channel.Description, 40)</div>
                        </div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </div>
                }
            }
        </div>
    </div>

    @if (_activeChannel is not null)
    {
        <!-- Main Message Area -->
        <div class="main-area">
            <div class="message-header">
                <div class="message-header-name"># @_activeChannel.Name</div>
                <div class="message-header-desc">@_activeChannel.Description</div>
            </div>

            <div class="message-list" id="message-list">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }

                @if (_messages is not null)
                {
                    @foreach (var msg in _messages.Where(m => m.ReplyToId is null))
                    {
                        <div class="message-item">
                            <div class="message-actions">
                                <button class="action-btn" @onclick="() => OpenThread(msg)">💬 Reply</button>
                                <div class="emoji-picker-wrapper">
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                    @if (_emojiPickerMessageId == msg.Id)
                                    {
                                        <div class="emoji-picker">
                                            @foreach (var emoji in _availableEmojis)
                                            {
                                                <button class="emoji-btn" @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                            }
                                        </div>
                                    }
                                </div>
                            </div>

                            <div>
                                <span class="message-author">@msg.Author</span>
                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <span class="reaction-badge" @onclick="() => AddReactionAsync(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji <span class="reaction-count">@reaction.Users.Count</span>
                                        </span>
                                    }
                                </div>
                            }

                            @if (GetReplyCount(msg.Id) > 0)
                            {
                                <span class="thread-link" @onclick="() => OpenThread(msg)">
                                    @GetReplyCount(msg.Id) replies
                                </span>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <div class="input-wrapper">
                    <textarea @bind="_messageInput" @bind:event="oninput"
                              placeholder="Message #@_activeChannel.Name"
                              @onkeydown="HandleMessageKeyDown"
                              rows="1"></textarea>
                    <button class="send-btn" disabled="@(_sendingMessage || string.IsNullOrWhiteSpace(_messageInput))"
                            @onclick="SendMessageAsync">
                        @(_sendingMessage ? "Sending…" : "Send")
                    </button>
                </div>
            </div>
        </div>

        <!-- Thread Panel -->
        @if (_activeThreadRootId is not null && _threadRootMessage is not null)
        {
            <div class="thread-panel">
                <div class="thread-header">
                    <span>Thread</span>
                    <button class="thread-close-btn" @onclick="CloseThread">✕</button>
                </div>

                <div class="quoted-message">
                    <div class="quoted-author">@_threadRootMessage.Author</div>
                    <div class="quoted-content">@_threadRootMessage.Content</div>
                </div>

                <div class="thread-replies" id="thread-replies">
                    @if (_threadReplies is not null)
                    {
                        @foreach (var reply in _threadReplies)
                        {
                            <div class="thread-reply-item">
                                <div>
                                    <span class="message-author">@reply.Author</span>
                                    <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                                </div>
                                <div class="message-content">@reply.Content</div>
                            </div>
                        }
                    }
                </div>

                <div class="message-input-area">
                    <div class="input-wrapper">
                        <textarea @bind="_threadReplyInput" @bind:event="oninput"
                                  placeholder="Reply…"
                                  @onkeydown="HandleThreadKeyDown"
                                  rows="1"></textarea>
                        <button class="send-btn" disabled="@(_sendingReply || string.IsNullOrWhiteSpace(_threadReplyInput))"
                                @onclick="SendThreadReplyAsync">
                            @(_sendingReply ? "Sending…" : "Reply")
                        </button>
                    </div>
                </div>
            </div>
        }
    }
    else
    {
        <div class="no-channel-selected">
            Select a channel to start chatting
        </div>
    }
</div>

@code {
    private List<Channel>? _channels;
    private Channel? _activeChannel;
    private List<Message>? _messages;
    private int _skip;
    private const int PageSize = 50;
    private bool _loadingMore;
    private bool _hasMore = true;

    private int? _activeThreadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;

    private string _messageInput = string.Empty;
    private string _threadReplyInput = string.Empty;

    private int? _emojiPickerMessageId;
    private bool _sendingMessage;
    private bool _sendingReply;

    private Dictionary<int, int> _replyCounts = new();

    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<Chat>? _dotNetRef;

    private static readonly string[] _availableEmojis = ["👍", "❤️", "😂", "🎉", "👀", "🔥"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./Components/Pages/Chat.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
            await _jsModule.InvokeVoidAsync("initScrollHandler", _dotNetRef, "message-list");
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannel = channel;
        _skip = 0;
        _hasMore = true;
        _messages = null;
        _emojiPickerMessageId = null;
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;
        _skip = messages.Count;
        _hasMore = messages.Count == PageSize;

        ComputeReplyCounts();

        await ChatService.MarkChannelReadAsync(channel.Id);

        StateHasChanged();

        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", "message-list");
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingMore || !_hasMore || _activeChannel is null)
            return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _skip, PageSize);
        if (older.Count > 0 && _messages is not null)
        {
            _messages.InsertRange(0, older);
            _skip += older.Count;
            ComputeReplyCounts();
        }
        _hasMore = older.Count == PageSize;
        _loadingMore = false;

        StateHasChanged();
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_messageInput) || _activeChannel is null)
            return;

        _sendingMessage = true;
        var content = _messageInput;
        _messageInput = string.Empty;

        try
        {
            var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
            _messages ??= new();
            _messages.Add(msg);
            _skip++;

            StateHasChanged();

            await Task.Yield();
            if (_jsModule is not null)
            {
                await _jsModule.InvokeVoidAsync("scrollToBottom", "message-list");
            }
        }
        finally
        {
            _sendingMessage = false;
        }
    }

    private async Task HandleMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task OpenThread(Message rootMessage)
    {
        _activeThreadRootId = rootMessage.Id;
        _threadRootMessage = rootMessage;
        _threadReplyInput = string.Empty;

        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        StateHasChanged();
    }

    private void CloseThread()
    {
        _activeThreadRootId = null;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadReplyInput = string.Empty;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyInput) || _activeChannel is null || _activeThreadRootId is null)
            return;

        _sendingReply = true;
        var content = _threadReplyInput;
        _threadReplyInput = string.Empty;

        try
        {
            var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _activeThreadRootId);
            _threadReplies ??= new();
            _threadReplies.Add(reply);

            // Update reply count
            if (_replyCounts.ContainsKey(_activeThreadRootId.Value))
                _replyCounts[_activeThreadRootId.Value]++;
            else
                _replyCounts[_activeThreadRootId.Value] = 1;

            // Also add to main message list so counts stay in sync
            _messages?.Add(reply);

            StateHasChanged();
        }
        finally
        {
            _sendingReply = false;
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ChatService.AddReactionAsync(messageId, emoji);

        // Update local message reactions
        var msg = _messages?.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
            }
        }

        StateHasChanged();
    }

    private void ComputeReplyCounts()
    {
        _replyCounts.Clear();
        if (_messages is null) return;

        foreach (var msg in _messages)
        {
            if (msg.ReplyToId is not null)
            {
                if (_replyCounts.TryGetValue(msg.ReplyToId.Value, out var count))
                    _replyCounts[msg.ReplyToId.Value] = count + 1;
                else
                    _replyCounts[msg.ReplyToId.Value] = 1;
            }
        }
    }

    private int GetReplyCount(int messageId)
    {
        return _replyCounts.TryGetValue(messageId, out var count) ? count : 0;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        if (diff.TotalSeconds < 60)
            return "just now";
        if (diff.TotalMinutes < 2)
            return "1 min ago";
        if (diff.TotalMinutes < 60)
            return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 2)
            return "1 hour ago";
        if (diff.TotalHours < 24)
            return $"{(int)diff.TotalHours} hours ago";
        if (diff.TotalDays < 2)
            return "yesterday";

        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateText(string text, int maxLength)
    {
        if (string.IsNullOrEmpty(text) || text.Length <= maxLength)
            return text;
        return text[..maxLength] + "…";
    }

    public async ValueTask DisposeAsync()
    {
        _dotNetRef?.Dispose();
        if (_jsModule is not null)
        {
            try { await _jsModule.DisposeAsync(); } catch { }
        }
    }
}

namespace sv_acdccdac2a064ac39b80468c3f1b49b3;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

namespace sv_acdccdac2a064ac39b80468c3f1b49b3;

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

export function initScrollHandler(dotNetRef, elementId) {
    const el = document.getElementById(elementId);
    if (!el) return;
    el.addEventListener('scroll', () => {
        if (el.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

export function scrollToBottom(elementId) {
    const el = document.getElementById(elementId);
    if (el) {
        el.scrollTop = el.scrollHeight;
    }
}

