+    border-top: 1px solid #e3e5e8;
+    background-color: #ffffff;
+    flex-shrink: 0;
+}
+
+.input-wrapper {
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
+
+.input-wrapper textarea {
+    flex: 1;
+    border: 1px solid #e3e5e8;
+    border-radius: 8px;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    outline: none;
+    font-family: inherit;
+    line-height: 1.4;
+}
+
+.input-wrapper textarea:focus {
+    border-color: #5865f2;
+    box-shadow: 0 0 0 2px rgba(88, 101, 242, 0.2);
+}
+
+.send-btn {
+    background-color: #5865f2;
+    color: #ffffff;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 20px;
+    font-size: 0.9rem;
+    font-weight: 600;
+    cursor: pointer;
+    transition: background-color 0.15s;
+    white-space: nowrap;
+}
+
+.send-btn:hover {
+    background-color: #4752c4;
+}
+
+.send-btn:disabled {
+    background-color: #a5b1c2;
+    cursor: not-allowed;
+}
+
+/* Loading */
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    color: #72767d;
+    font-size: 0.85rem;
+}
+
+/* No channel selected */
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    flex: 1;
+    color: #72767d;
+    font-size: 1.1rem;
+}
+

diff --git a/tmp/sv-acdccdac2a064ac39b80468c3f1b49b3/Components/Pages/Chat.razor b/tmp/sv-acdccdac2a064ac39b80468c3f1b49b3/Components/Pages/Chat.razor
