409.         if (diff.TotalMinutes < 2)
410.             return "1 min ago";
411.         if (diff.TotalMinutes < 60)
412.             return $"{(int)diff.TotalMinutes} min ago";
413.         if (diff.TotalHours < 2)
414.             return "1 hour ago";
415.         if (diff.TotalHours < 24)
416.             return $"{(int)diff.TotalHours} hours ago";
417.         if (diff.TotalDays < 2)
