     box-shadow: 0 0 0 2px rgba(88, 101, 242, 0.2);
 }

 .send-btn {
     background-color: #5865f2;
     color: #ffffff;
     border: none;
     border-radius: 8px;
     padding: 10px 20px;
     font-size: 0.9rem;
     font-weight: 600;
     cursor: pointer;
     transition: background-color 0.15s;
     white-space: nowrap;
 }

 .send-btn:hover {
     background-color: #4752c4;
 }

 .send-btn:disabled {
     background-color: #a5b1c2;
     cursor: not-allowed;
 }

 /* Loading */
 .loading-indicator {
     text-align: center;
     padding: 12px;
     color: #72767d;
     font-size: 0.85rem;
 }

 /* No channel selected */
 .no-channel-selected {
     display: flex;
     align-items: center;
     justify-content: center;
     flex: 1;
     color: #72767d;
     font-size: 1.1rem;
 }

